const data = $input.first().json;
const store = $getWorkflowStaticData('global');
store.seen = store.seen || {};
store.prs = store.prs || {};

const out = [];

for (const r of data.repos || []) {
  if (r.state === 'failed') {
    if (store.seen[r.repo] !== r.url) {
      store.seen[r.repo] = r.url;
      const short = r.repo.split('/')[1] || r.repo;
      const where = [r.stage, r.branch].filter(Boolean).join(' on ');
      out.push({ json: { text: '\u274c <b>' + short + '</b>\n' + where + '\n' + (r.url || '') } });
    }
  } else {
    delete store.seen[r.repo];
  }

  const open = {};
  for (const pr of r.open_prs || []) {
    open[pr.number] = true;
    const key = r.repo + '#' + pr.number;
    if (store.prs[key]) continue;
    store.prs[key] = true;
    const short = r.repo.split('/')[1] || r.repo;
    out.push({ json: { text: '\u{1F440} <b>' + short + '</b> waiting on you\n#' + pr.number + ' ' + pr.title + '\n' + pr.url } });
  }
  for (const key of Object.keys(store.prs)) {
    if (!key.startsWith(r.repo + '#')) continue;
    if (!open[key.split('#')[1]]) delete store.prs[key];
  }
}

return out;
